import subprocess
import json
import time
import sys

def call_mcp():
    process = subprocess.Popen(
        ['npx', '-y', 'mcp-remote', 'https://prod.dashboard.nexlev.io/api/claude-mcp'],
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True
    )

    # Send initialize
    init_req = {
        "jsonrpc": "2.0",
        "id": 1,
        "method": "initialize",
        "params": {
            "protocolVersion": "2024-11-05",
            "capabilities": {},
            "clientInfo": {"name": "test", "version": "1.0"}
        }
    }
    process.stdin.write(json.dumps(init_req) + "\n")
    process.stdin.flush()

    # Read response
    while True:
        line = process.stdout.readline()
        if not line:
            break
        print("INIT RESP:", line.strip())
        break

    # Send initialized notification
    init_notif = {
        "jsonrpc": "2.0",
        "method": "notifications/initialized"
    }
    process.stdin.write(json.dumps(init_notif) + "\n")
    process.stdin.flush()

    # Send tool call
    tool_req = {
        "jsonrpc": "2.0",
        "id": 2,
        "method": "tools/call",
        "params": {
            "name": "get_channel_analytics",
            "arguments": {
                "channel_id": "https://www.youtube.com/@EverythingProfessor"
            }
        }
    }
    process.stdin.write(json.dumps(tool_req) + "\n")
    process.stdin.flush()

    while True:
        line = process.stdout.readline()
        if not line:
            break
        print("TOOL RESP:", line.strip())
        if '"id":2' in line or '"id": 2' in line:
            break

    process.kill()

call_mcp()
